{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "The closest oxazolidinone analogue, LCB01-0371 (delpazolid), sharing the same N-aryl-oxazolidinone core and fluorophenyl substitution, showed 99.75% absolute oral bioavailability in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Linezolid, the prototypical oxazolidinone with the same core and fluorophenyl/morpholine motif, has approximately 100% oral bioavailability in humans, supporting high F for this oxazolidinone class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fosravuconazole, a phosphate ester prodrug like the query, achieved 100% oral bioavailability in humans, supporting the concept that the phosphate prodrug moiety can yield complete oral absorption after conversion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "YH4808, another oxazolidinone analogue, had low absolute bioavailability (10.1%), providing a class counterexample; however, its thiomorpholine and acetamide side chain differ from the query's tetrazole-pyridine and phosphate prodrug motif, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cadazolid showed very low oral bioavailability, but it is an oxazolidinone intentionally designed for local gastrointestinal action, so its low F is not representative of systemically absorbed oxazolidinones such as the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphate ester prodrug of a tedizolid-like oxazolidinone. The closest oxazolidinone analogues (delpazolid, linezolid) show essentially complete oral bioavailability in humans, and a phosphate prodrug of another azole (fosravuconazole) also shows 100% F. The low-F oxazolidinone examples (YH4808, cadazolid) are structurally distinct or intentionally nonabsorbed, so they do not override the strong class trend. Therefore predict high F (>=20%).",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query (tedizolid phosphate) is present; the closest records are for other oxazolidinones and phosphate prodrugs.",
    "The effect of the phosphate ester on absorption and first-pass hydrolysis is inferred from prodrug analogues rather than directly measured for this molecule."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

